package de.kopfzentrum.gam.communication;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/settings/communication-workflow") public class CommunicationWorkflowSettingsController{private final CommunicationWorkflowSettingsRepository repo;public CommunicationWorkflowSettingsController(CommunicationWorkflowSettingsRepository repo){this.repo=repo;}@GetMapping public CommunicationWorkflowSettings get(@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.load();}@PutMapping public CommunicationWorkflowSettings put(@RequestBody CommunicationWorkflowSettings v,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.save(v,u.getUsername());}private void req(AuthenticatedUser u){if(u==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);}}
